+(() => {
+  const backdrop     = document.getElementById('deleteModal');
+  const imageNameEl  = document.getElementById('modalImageName');
+  const cancelBtn    = document.getElementById('cancelBtn');
+  const closeBtn     = document.getElementById('modalCloseBtn');
+  const confirmBtn   = document.getElementById('confirmDeleteBtn');
+
+  let pendingCard = null;
+
+  function openModal(imageName, card) {
+    pendingCard = card;
+    imageNameEl.textContent = imageName;
+    backdrop.classList.add('is-open');
+    backdrop.setAttribute('aria-hidden', 'false');
+    // Return focus to confirm on open for accessibility
+    confirmBtn.focus();
+  }
+
+  function closeModal() {
+    backdrop.classList.remove('is-open');
+    backdrop.setAttribute('aria-hidden', 'true');
+    pendingCard = null;
+  }
+
+  // Open on any .trigger click
+  document.querySelectorAll('.trigger').forEach(btn => {
+    btn.addEventListener('click', () => {
+      const imageName = btn.dataset.image || 'this image';
+      const card = btn.closest('.photo-card');
+      openModal(imageName, card);
+    });
+  });
+
+  // Close actions
+  cancelBtn.addEventListener('click', closeModal);
+  closeBtn.addEventListener('click', closeModal);
+
+  // Close on backdrop click (outside modal panel)
+  backdrop.addEventListener('click', e => {
+    if (e.target === backdrop) closeModal();
+  });
+
+  // Close on Escape
+  document.addEventListener('keydown', e => {
+    if (e.key === 'Escape' && backdrop.classList.contains('is-open')) closeModal();
+  });
+
+  // Confirm delete
+  confirmBtn.addEventListener('click', () => {
+    if (pendingCard) {
+      pendingCard.style.transition = 'opacity .3s ease, transform .3s ease';
+      pendingCard.style.opacity = '0';
+      pendingCard.style.transform = 'scale(.95)';
+      setTimeout(() => pendingCard.remove(), 300);
+    }
+    closeModal();
+  });
+})();
